css:
body {
	margin: 0;
	font-family: sans-serif;
}

/* The notes app's page-wide focus ring: it reaches html and body too, which a phone never focuses. */
:focus-visible {
	outline: 2px solid #1d4ed8;
	outline-offset: 2px;
}

a {
	color: #1d4ed8;
	text-decoration: none;
}

.home.mk-wgvluz {
				padding: 24px;
				background: #f4f1ea;
				color: #1d1b16;
				font-size: 18px;
			}
			.heading.mk-wgvluz {
				margin: 0 0 16px;
				font-size: 28px;
				font-weight: 700;
			}
			.card.mk-wgvluz {
				display: block;
				padding: 12px 16px;
				border: 1px solid #ced4da;
				border-radius: 10px;
				background: #ffffff;
			}
